tool_calls:
mkdir -p /release
awk '
{
  # match type(scope): message
  # find positions
  line=$0
  # extract type: before "("
  p1=index(line, "(")
  p2=index(line, "):")
  if (p1>0 && p2>p1) {
    type=substr(line,1,p1-1)
    scope=substr(line,p1+1,p2-p1-1)
    message=substr(line,p2+2)
    # trim leading spaces/colon spaces
    sub(/^:[[:space:]]*/, "", message)
    sub(/^[[:space:]]+/, "", message)
    sub(/^[[:space:]]+/, "", type)
    sub(/[[:space:]]+$/, "", type)
    item="- " scope ": " message
    if (type=="feat") {
      feats[++nf]=item
    } else if (type=="fix") {
      fixes[++nx]=item
    } else {
      others[++no]=item
    }
  }
}
END {
  print "## Features" > "/release/CHANGELOG.md"
  for (i=1;i<=nf;i++) print feats[i] >> "/release/CHANGELOG.md"
  print "" >> "/release/CHANGELOG.md"
  print "## Bug Fixes" >> "/release/CHANGELOG.md"
  for (i=1;i<=nx;i++) print fixes[i] >> "/release/CHANGELOG.md"
  print "" >> "/release/CHANGELOG.md"
  print "## Other" >> "/release/CHANGELOG.md"
  for (i=1;i<=no;i++) print others[i] >> "/release/CHANGELOG.md"
}
' /data/commits.log
cat /release/CHANGELOG.md

